import { supabase } from "@/lib/supabase"
import ProductCard from "@/components/product-card"
import Header from "@/components/header"
import Footer from "@/components/footer"
import { notFound } from "next/navigation"

export const revalidate = 60 // Revalidate every minute

export default async function CategoryPage({ params }: { params: { slug: string } }) {
    // 1. Fetch Category ID from slug
    const { data: category } = await supabase
        .from('categories')
        .select('id, name, description')
        .eq('slug', params.slug)
        .single()

    if (!category) {
        notFound()
    }

    // 2. Fetch Products for this Category
    const { data: products } = await supabase
        .from('products')
        .select('*, category:categories(name)')
        .eq('category_id', category.id)
        .order('created_at', { ascending: false })

    // Transform for ProductCard
    const transformedProducts = (products || []).map((p: any) => ({
        id: p.id,
        name: p.name,
        category: p.category?.name || category.name,
        price: p.price,
        originalPrice: p.sale_price || undefined,
        image: p.images?.[0] || "",
        rating: 4.8, // Default
        reviews: 0,
        isNew: p.is_new
    }))

    return (
        <div className="w-full min-h-screen bg-background flex flex-col">
            <Header />

            <main className="flex-grow">
                <div className="bg-secondary/30 py-12 px-4">
                    <div className="max-w-7xl mx-auto">
                        <h1 className="text-4xl font-bold text-foreground mb-4">{category.name}</h1>
                        {category.description && (
                            <p className="text-muted-foreground text-lg max-w-2xl">{category.description}</p>
                        )}
                    </div>
                </div>

                <div className="max-w-7xl mx-auto px-4 py-12">
                    {transformedProducts.length > 0 ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                            {transformedProducts.map((product) => (
                                <ProductCard key={product.id} product={product} />
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-20">
                            <p className="text-xl text-muted-foreground">No products found in this category.</p>
                        </div>
                    )}
                </div>
            </main>

            <Footer />
        </div>
    )
}
